-- order_info: 2023-11-01 ~ 2024-11-30 (2024-11은 API 데이터와 대조용)
SELECT AX_ETC, SERVICE_AMT, COUPON_VALUE, YN_VAT, GROSS_AMT, DC_AMT, AX_POINT, COUPON_DESC, SALE_STAT, DC_USED_RATE, UP_DATE, TAXRATE, AX_CMSDC, DT_CLOSE, AX_COUPON, ORDER_DATE, POS_NO, RET_INV_SEQ, YN_CREDIT, AX_CREDIT, STORE_CODE, TBL_CLA1NAME, AX_DC, YN_COUPON, AX_BANK, QTY_SUM, AX_CASH, DC_USED_TYPE, PRODUCT_AMT, ORDER_POS_NO, YN_END, DC_REASON_CODE, DEPOSIT_FEE, SERVICE_FEE, INV_PRTNUM, TBL_CLA2NAME, AX_AMT, ID_MEMO, NET_AMT, ETC_CHARGE, COUPON_AMT, AX_CARD, SALE_TYPE, ROW_NUM, SUB_TOT, SALE_DATE, GRAND_TOTAL, YN_CLOSE, CLOSE_DATE, TBL_CLA1, TBL_CLA2, NOTAX_TOT, CR_DATE, INV_SEQ, COUPON_CODE, YN_PRINT, AX_CASHRECEPT, DC_REASON_DESC, COUPON_COUNT, TAX_TOT
FROM order_info
WHERE SALE_DATE >= '2023-11-01' AND SALE_DATE < '2024-12-01';
